CREATE SCHEMA IF NOT EXISTS watchlist;
SET LOCAL search_path TO watchlist;
REVOKE ALL ON SCHEMA watchlist FROM PUBLIC;
CREATE TABLE IF NOT EXISTS schema_version(version INTEGER PRIMARY KEY);
INSERT INTO schema_version VALUES(1) ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS instruments(id TEXT PRIMARY KEY, market TEXT NOT NULL, code TEXT NOT NULL, name TEXT NOT NULL, asset_class TEXT NOT NULL CHECK(asset_class='stock'), currency TEXT NOT NULL CHECK(currency='CNY'), provenance TEXT NOT NULL, UNIQUE(market,code));
CREATE TABLE IF NOT EXISTS tasks(id TEXT PRIMARY KEY, owner TEXT NOT NULL, name TEXT NOT NULL, instrument_id TEXT REFERENCES instruments(id), version INTEGER NOT NULL, generation INTEGER NOT NULL DEFAULT 0, lifecycle TEXT NOT NULL, created_at DOUBLE PRECISION NOT NULL, updated_at DOUBLE PRECISION NOT NULL);
CREATE TABLE IF NOT EXISTS rule_versions(task_id TEXT REFERENCES tasks(id), version INTEGER NOT NULL, spec TEXT NOT NULL, created_at DOUBLE PRECISION NOT NULL, change_summary TEXT NOT NULL, PRIMARY KEY(task_id,version));
CREATE OR REPLACE FUNCTION reject_rule_update() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION 'immutable_rule_version'; END;
$$;
DROP TRIGGER IF EXISTS immutable_rule_versions ON rule_versions;
CREATE TRIGGER immutable_rule_versions BEFORE UPDATE ON rule_versions FOR EACH ROW EXECUTE FUNCTION reject_rule_update();
CREATE TABLE IF NOT EXISTS runtime(task_id TEXT PRIMARY KEY REFERENCES tasks(id), state TEXT NOT NULL, next_run DOUBLE PRECISION, lease_token TEXT, lease_until DOUBLE PRECISION, last_checked DOUBLE PRECISION, last_success DOUBLE PRECISION, health TEXT NOT NULL DEFAULT 'pending', decision TEXT, pause_at DOUBLE PRECISION);
CREATE TABLE IF NOT EXISTS runs(id TEXT PRIMARY KEY, task_id TEXT NOT NULL, version INTEGER NOT NULL, generation INTEGER NOT NULL, lease_token TEXT NOT NULL, scheduled_for DOUBLE PRECISION NOT NULL, started_at DOUBLE PRECISION NOT NULL, finished_at DOUBLE PRECISION, status TEXT NOT NULL, result TEXT, decision TEXT, detail TEXT NOT NULL, FOREIGN KEY(task_id,version) REFERENCES rule_versions(task_id,version));
CREATE TABLE IF NOT EXISTS observations(id TEXT PRIMARY KEY, instrument_id TEXT REFERENCES instruments(id), field TEXT, value TEXT, unit TEXT, source_time TEXT, fetched_at TEXT, provider TEXT, source_ref TEXT, quality TEXT NOT NULL, reason_code TEXT);
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY, instrument_id TEXT REFERENCES instruments(id), provider TEXT NOT NULL, source_key TEXT NOT NULL, source_time TEXT, fetched_at TEXT, event_type TEXT NOT NULL, UNIQUE(provider,source_key));
CREATE TABLE IF NOT EXISTS calendar_entries(task_id TEXT NOT NULL, version INTEGER NOT NULL, scheduled_at DOUBLE PRECISION NOT NULL, PRIMARY KEY(task_id,version), FOREIGN KEY(task_id,version) REFERENCES rule_versions(task_id,version));
CREATE TABLE IF NOT EXISTS evidence(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(id), observation_id TEXT REFERENCES observations(id), event_id TEXT REFERENCES events(id), detail TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notifications(id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(id), run_id TEXT NOT NULL REFERENCES runs(id), dedup_key TEXT NOT NULL UNIQUE, created_at DOUBLE PRECISION NOT NULL, read_at DOUBLE PRECISION, detail TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, task_id TEXT REFERENCES tasks(id), at DOUBLE PRECISION NOT NULL, action TEXT NOT NULL, detail TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS parser_audit(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, at DOUBLE PRECISION NOT NULL, model TEXT NOT NULL, prompt_version TEXT NOT NULL, outcome TEXT NOT NULL, detail TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ticks(id TEXT PRIMARY KEY, started_at DOUBLE PRECISION NOT NULL, finished_at DOUBLE PRECISION, outcome TEXT);
CREATE INDEX IF NOT EXISTS due_tasks ON runtime(next_run);
CREATE INDEX IF NOT EXISTS task_runs ON runs(task_id,started_at);
CREATE INDEX IF NOT EXISTS task_owner ON tasks(owner,lifecycle);

REVOKE ALL ON ALL TABLES IN SCHEMA watchlist FROM PUBLIC;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA watchlist FROM PUBLIC;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA watchlist FROM PUBLIC;
